mapper.select:
SELECT COUNT(*) FROM ai_scene_orchestration_step
WHERE orchestration_id = #{orchestrationId} AND step_index = #{stepIndex}
AND id != #{excludeId}

mapper.update:
UPDATE ai_scene_orchestration_step
step_index = #{stepIndex}, step_name = #{stepName}, agent_id = #{agentId}, input_mapping = #{inputMapping}, `condition` = #{condition}, retry_count = #{retryCount}, timeout_ms = #{timeoutMs}, status = #{status}, sort_order = #{sortOrder}, updated_at = NOW(),
WHERE id = #{id}

update.foreach:
UPDATE ai_scene_orchestration_step
SET step_index = #{idx} + 1
WHERE id = #{stepId} AND orchestration_id = #{orchestrationId}
